style.css:
@-moz-document domain("pinterest.com") {
/* MAIN BACKGROUND IMAGE */
body {
    background-image:
    url("https://i.pinimg.com/1200x/4e/ea/55/4eea55f530badfb5a942eb1984a4ea6e.jpg") !important;

    background-size:cover !important;
    background-position:center !important;
    background-attachment:fixed !important;
    background-repeat:no-repeat !important;
}


/* MAKE PINTEREST TRANSPARENT */
[data-test-id="unauth-header"],
header,
main,
div {
    background-color:transparent;
}


/* TOP NAV BAR */
header {

    background:
    linear-gradient(
        90deg,
        rgba(255,220,235,.90),
        rgba(215,240,255,.90)
    ) !important;

    backdrop-filter:blur(15px);
}


/* SEARCH BAR */
input {

    background:
    linear-gradient(
        90deg,
        #ffe4ef,
        #e0f5ff
    ) !important;

    border-radius:30px!important;

    color:#c85b8c!important;

    border:2px solid #f5b7d2!important;
}


/* SEARCH TEXT */
input::placeholder {

    color:#c85b8c!important;
}


/* PIN CARDS */
[data-test-id="pin"] {

    background:
    linear-gradient(
        135deg,
        rgba(255,225,240,.85),
        rgba(220,245,255,.85)
    ) !important;

    border-radius:20px!important;

    backdrop-filter:blur(10px);

    box-shadow:
    0 5px 20px rgba(255,160,200,.25);

    transition:.3s;
}


[data-test-id="pin"]:hover {

    box-shadow:

    0 0 18px #ffb6d6,
    0 0 25px #a9e4ff;
}


/* TEXT COLORS */
h1,
h2,
h3,
span,
a,
div {

    color:#c85b8c;
}


/* BUTTONS */

button {

    background:
    linear-gradient(
        90deg,
        #ffd1e5,
        #cdefff
    ) !important;

    color:#c85b8c!important;

    border-radius:30px!important;

    border:none!important;
}


/* PROFILE / MENU AREAS */

[role="menu"],
[role="dialog"] {

    background:
    linear-gradient(
        180deg,
        #ffe3ef,
        #dff5ff
    ) !important;

    border-radius:20px!important;

}


/* SCROLL BAR */

::-webkit-scrollbar {

    width:10px;
}


::-webkit-scrollbar-thumb {

    background:
    linear-gradient(
        #ffb6d6,
        #a9e4ff
    );

    border-radius:20px;
}


/* SOFT GLOW */

button:hover,
input:hover {

    box-shadow:
    0 0 10px #ffb6d6,
    0 0 15px #a9e4ff;
}
}
